from functools import lru_cache
V=[tuple(map(int,l.split())) for l in open('/tmp/h/visited.txt')]
def avail(f,t,n,j): return (0 if j==50 else f, 0 if j==20 else t, 0 if j==10 else n)
@lru_cache(None)
def best(a,f,t,n):
    c=[(x+y+z,(x,y,z)) for x in range(f+1) for y in range(t+1) for z in range(n+1) if 50*x+20*y+10*z==a]
    return min(c)[1] if c else None
def exp(b,w,f,t,n,j,a):
    if a<=0 or a%10: return 'Inv',None
    if w+a>200: return 'Lim',None
    fee=5 if a>100 else 0
    if a+fee>b: return 'Ins',None
    c=best(a,*avail(f,t,n,j))
    if c is None: return 'Cant',None
    return 'Ok',c
R={}
def add(k,v): R.setdefault(k,[]).append(v)
for v in V:
    b,w,f,t,n,j,a=v; st,c=exp(*v); fee=5 if a>100 else 0
    if st=='Ok':
        tot=sum(c)
        if b==a+fee and tot>=6: add('exact&Q6',v)
        if tot>=6 and w>0: add('Q6&w>0',v)
        if tot>=6 and b<250: add('Q6&b<250',v)
        if tot>=6: add('Q6',v)
        if tot>=9: add('Q9',v)
        jc={50:f,20:t,10:n}.get(j,0)
        if a>100 and jc>0 and w>0: add('QJ&w>0',v)
        if a>100 and jc>0 and b==a+fee: add('QJ&exact',v)
for k,l in R.items(): print(k,len(l),l[:4])
EOF
